 return previewable(value)?<button className="artifact-row artifact-document" onClick={()=>onOpen(value)}><File size={16}/><span><b>{name}</b><small>{mime} · {artifactSize(item)}</small></span><Maximize2 size={14}/></button>:<a className="artifact-row" href={url} download><File size={16}/><span><b>{name}</b><small>{mime} · {artifactSize(item)}</small></span><Download size={14}/></a>
